{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have access logging enabled, which is critical for tracking access and detecting unauthorized access attempts."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block, which could lead to unintended public exposure of sensitive data."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a lifecycle configuration, which is important for managing object lifecycle and optimizing storage costs."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }

  force_destroy = true

  logging {
    target_bucket = "${aws_s3_bucket.logs_target.bucket}"
    target_prefix = "${local.resource_prefix.value}/logs/"
  }

  lifecycle_rule {
    id      = "log-lifecycle"
    enabled = true

    expiration {
      days = 365
    }

    noncurrent_version_expiration {
      days = 30
    }
  }

  public_access_block {
    block_public_acls       = true
    block_public_policy     = true
    ignore_public_acls      = true
    restrict_public_buckets = true
  }

  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket" "logs_target" {
  bucket = "${local.resource_prefix.value}-logs-target"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }

  tags = merge({
    Name        = "${local.resource_prefix.value}-logs-target"
    Environment = local.resource_prefix.value
    }, {
  })
}
",
  "fix_summary": "Enabled access logging by adding a logging block with a target bucket. Added a lifecycle rule to manage object expiration and noncurrent version expiration. Configured a Public Access block to prevent unintended public exposure."
}
